import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_res_ops_kernel(const float* original_x, const float* bias, float* out, 
                                    int N, int C, int D, int H, int W, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    int elements_per_channel = D * H * W;
    int c = (idx / elements_per_channel) % C;

    float o_val = original_x[idx];
    float b_val = bias[c];
    out[idx] = o_val * (2.0f * o_val + b_val + 1.0f);
}

torch::Tensor fused_res_ops_cuda(torch::Tensor original_x, torch::Tensor bias) {
    TORCH_CHECK(original_x.dim() == 5, "original_x must be 5D");
    TORCH_CHECK(bias.dim() == 4 && bias.size(1) == 1 && bias.size(2) == 1 && bias.size(3) == 1,
               "bias must have shape (C,1,1,1)");

    auto out = torch::empty_like(original_x);
    int total_elements = original_x.numel();
    int N = original_x.size(0);
    int C = original_x.size(1);
    int D = original_x.size(2);
    int H = original_x.size(3);
    int W = original_x.size(4);

    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_res_ops_kernel<<<num_blocks, block_size>>>(
        original_x.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W,
        total_elements
    );

    return out;
}
"""

fused_ops_cpp_source = "torch::Tensor fused_res_ops_cuda(torch::Tensor original_x, torch::Tensor bias);"

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_res_ops_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, 
                                                stride=stride, padding=padding, 
                                                output_padding=output_padding)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.conv_transpose(x)
        original_x = x  # Gradient flows through original_x in this implementation
        x = self.fused_ops.fused_res_ops_cuda(original_x, self.bias)
        return x
